/// <returns>Company reference</returns>
public RecId deliveryAddressPartyRecId()
{
    return CompanyInfo::current();
}

    /// <summary>
    /// The <c>IsDeliveryAddressOrderSpecific</c> field is only designed for import scenarios
    /// </summary>
    /// <returns>return 'No' for export scenarios to save performance.</returns>
    private static str isDeliveryAddressOrderSpecificComputedColumnDefinition()
    {

        return SysComputedColumn::returnLiteral(NoYes::No);
    }

    /// <summary>
    /// Change tracking querty
    /// </summary>
    /// <returns>Query for change tracking</returns>
    public static Query defaultCTQuery()
    {
        Query purchaseOrderHeaderQuery = new Query();

        var purchTableDS = purchaseOrderHeaderQuery.addDataSource(tableNum(PurchTable));

        var accDistributionTemplDS = purchTableDS.addDataSource(tableNum(AccountingDistributionTemplate));
        accDistributionTemplDS.joinMode(JoinMode::OuterJoin);
        accDistributionTemplDS.addLink(fieldNum(PurchTable, AccountingDistributionTemplate), fieldNum(AccountingDistributionTemplate, RecId));
        
        var confirmingPODS = purchTableDS.addDataSource(tableNum(ConfirmingPO));
        confirmingPODS.joinMode(JoinMode::OuterJoin);
        confirmingPODS.relations(true);

        var vendInvoiceDeclISDS = purchTableDS.addDataSource(tableNum(VendInvoiceDeclaration_IS));
        vendInvoiceDeclISDS.joinMode(JoinMode::OuterJoin);
        vendInvoiceDeclISDS.relations(true);

        var dimAttributeValueSet = purchTableDS.addDataSource(tableNum(DimensionAttributeValueSet));
        dimAttributeValueSet.joinMode(JoinMode::OuterJoin);
        dimAttributeValueSet.addLink(fieldNum(PurchTable, DefaultDimension), fieldNum(DimensionAttributeValueSet, RecId));

        var reasonTableDS = purchTableDS.addDataSource(tableNum(ReasonTableRef));
        reasonTableDS.joinMode(JoinMode::OuterJoin);
        reasonTableDS.addLink(fieldNum(PurchTable, ReasonTableRef), fieldNum(ReasonTableRef, RecId));

        LogisticsPostalAddressBaseEntityChangeTrackingHelper::addPostalAddressBasedOnAddressRecIdLink(purchTableDS, fieldNum(PurchTable, DeliveryPostalAddress));

        var purchTableWDS = purchTableDS.addDataSource(tableNum(PurchTable_W));
        purchTableWDS.joinMode(JoinMode::OuterJoin);
        purchTableWDS.addLink(fieldNum(PurchTable, RecId), fieldNum(PurchTable_W, PurchTable));

        var logisticsPostalAddressDS = purchTableWDS.addDataSource(tableNum(LogisticsPostalAddress));
        logisticsPostalAddressDS.joinMode(JoinMode::OuterJoin);
        logisticsPostalAddressDS.addLink(fieldNum(PurchTable_W, InvoicePostalAddress_TH), fieldNum(LogisticsPostalAddress, RecId));

        var tmsPurchTableDS = purchTableDS.addDataSource(tableNum(TMSPurchTable));
        tmsPurchTableDS.joinMode(JoinMode::OuterJoin);
        tmsPurchTableDS.addLink(fieldNum(PurchTable, PurchId), fieldNum(TMSPurchTable, PurchId));

        var workerDS = purchTableDS.addDataSource(tableNum(HcmWorker));
        workerDS.joinMode(JoinMode::OuterJoin);
        workerDS.addLink(fieldNum(PurchTable, WorkerPurchPlacer), fieldNum(HcmWorker, RecId));

        workerDS = purchTableDS.addDataSource(tableNum(HcmWorker));
        workerDS.joinMode(JoinMode::OuterJoin);
        workerDS.addLink(fieldNum(PurchTable, Requester), fieldNum(HcmWorker, RecId));

        var transportationDocDS = purchTableDS.addDataSource(tableNum(TransportationDocument));
        transportationDocDS.joinMode(JoinMode::OuterJoin);
        transportationDocDS.addLink(fieldNum(PurchTable, TransportationDocument), fieldNum(TransportationDocument, RecId));

        return purchaseOrderHeaderQuery;
    }

    /// <summary>
    /// Update values
    /// </summary>
    public void postLoad()
    {
        super();

        if (strContains(this.FormattedDeliveryAddress, '%1'))
        {
            LogisticsAddressCountryRegionTranslation::replaceAddressTokenByFieldName(this, fieldStr(METPurchPurchaseOrderHeaderV2Entity, FormattedDeliveryAddress), fieldStr(METPurchPurchaseOrderHeaderV2Entity, DeliveryAddressCountryRegionId));
        }
        
    }

    /// <summary>
    /// MPJ_23295_CustomOdataAPIPORequestChange on 12 Apr 2022 by chaminda
    /// alternate method to following
    /// BudgetSourceCollectionIntegrator::isDocumentBudgetTracked(purchTable)
    /// </summary>
    /// <param name="purchId"> Get purchase order number</param>
    /// <returns> boolean </returns>
    public static boolean IsBudgetTracked(PurchId _purchId)
    {
        boolean     isTracked   = false;
        PurchTable  purchTable  = PurchTable::find(_purchId);
        SourceDocumentLine sourceDocumentLine = SourceDocumentLine::findBySourceDocumentHeader(purchTable.SourceDocumentHeader);
        while (!isTracked && sourceDocumentLine)
        {
            // Is there a budget being tracked?
            BudgetSourceInquiryDetails budgetDetails = BudgetSourceSourceDocumentLine::getBudgetSourceInquiryDetails(sourceDocumentLine);

            if (budgetDetails)
            {
                while (!isTracked && budgetDetails.next())
                {
                    isTracked = budgetDetails.currentAmountTracked() != 0;
                }
            }

            next sourceDocumentLine;
        }

        return isTracked;
    }

    /// <summary>
    /// CoC method for InsertEntityDataSource method
    /// </summary>
    /// <param name = "_entityCtx">Param of type DataEntityRuntimeContext</param>
    /// <param name = "_dataSourceCtx">Param of type DataEntityDataSourceRuntimeContext</param>
    /// <returns>true of false</returns>
    public boolean insertEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
    {
        boolean metRet;
        Common  metBuffer;
     
        if (_dataSourceCtx.name() == dataEntityDataSourceStr(PurchPurchaseOrderHeaderV2Entity, METPurchTable))
        {
            metBuffer = METPurchTable::find(this.PurchaseOrderNumber, true);
        }

        if (metBuffer)
        {
            _dataSourceCtx.setBuffer(metBuffer);
            _dataSourceCtx.setDatabaseOperation(DataEntityDatabaseOperation::Update);
            this.mapEntityToDataSource(_entityCtx, _dataSourceCtx);
        }
        metRet=super(_entityCtx,_dataSourceCtx);
        return metRet;
    }

/// <summary>    
/// Service method to cancel PO 
/// </summary>
/// <param name="dataAreaId"> Get company id</param>
/// <param name="purchId"> Get purchase order number</param>
[
    SysODataActionAttribute('CancelPO',false),
    SysODataCollectionAttribute("DataAreaId", Types::String),
    SysODataCollectionAttribute("PurchId", Types::String)
]
public static void cancelPO(DataAreaId dataAreaId, PurchId purchId)
{
    changecompany(dataAreaId)
    {
        PurchTable purchTable = PurchTable::find(purchId);
        if (purchTable)
        {
            PurchCancel purchCancel = PurchCancel::METconstruct();
            purchCancel.parmMETPurchTable(purchTable);
            purchCancel.runOperation();
        }
        else
        {
            throw Error("@MET:NoPurchOrderExist");
        }
        METPurchPurchaseOrderHeaderV2Entity::poSubmitToWorkflow(purchTable);
    }
}

    /// <summary>
    /// Purchase order submit to workflow
    /// </summary>
    /// <param name = "_purchTable">PurchTable</param>
    public static void poSubmitToWorkflow(PurchTable _purchTable)
    {
        str	comment;

        _purchTable.reread();

        if (_purchTable.DocumentState == VersioningDocumentState::Draft && _purchTable.ChangeRequestRequired)
        {
            comment = strFmt("@MET:POWorkFlowSubmittedFromPODE", _purchTable.PurchId);

            if (_purchTable.checkFullyDistributedAndQualified())
            {
                try
                {
                    ttsbegin;
                    _purchTable.selectForUpdate(true);
                    _purchTable.submitToWorkflow(workflowTypeStr(PurchTableTemplate), comment, false);
                    ttscommit;

                    if (_purchTable.DocumentState == VersioningDocumentState::InReview)
                    {
                        info(strFmt("@MET:POWorkflowSubmitted", _purchTable.PurchId));
                    }
                }
                catch (Exception::CLRError)
                {
                    System.Exception interopException = CLRInterop::getLastException();
                    error(strFmt("%1", interopException));
                }
                catch (Exception::Error)
                {
                    error(strFmt("@MET:POWorkFlowSubmissionFailed", _purchTable.PurchId));
                }
            }
        }
    }
